'use client';

import { LogIn } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

import { useAuthStore } from '@/stores/auth.store';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const login = useAuthStore((state: any) => state.login);
  const isLoading = useAuthStore((state: any) => state.isLoading);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    try {
      await login({ email, password });
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.response?.data?.message || 'Login failed');
    }
  };

  return (
    <>
      <div className="text-center">
        <div className="mx-auto h-12 w-12 bg-blue-100 dark:bg-blue-900 text-blue-600 dark:text-blue-300 rounded-full flex items-center justify-center mb-4">
          <LogIn className="h-6 w-6" />
        </div>
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Sign in to DevFlow Hub</h2>
        <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
          Or <Link href="/register" className="text-blue-600 hover:text-blue-500">create a new account</Link>
        </p>
      </div>
      <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
        {error && <div className="p-3 bg-red-100 text-red-700 rounded-md text-sm">{error}</div>}
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Email address</label>
            <input
              type="email"
              required
              className="mt-1 block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500"
              value={email}
              onChange={e => { setEmail(e.target.value); }}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Password</label>
            <input
              type="password"
              required
              className="mt-1 block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500"
              value={password}
              onChange={e => { setPassword(e.target.value); }}
            />
          </div>
        </div>
        <button
          type="submit"
          disabled={isLoading}
          className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
        >
          {isLoading ? 'Signing in...' : 'Sign in'}
        </button>
      </form>
    </>
  );
}

'use client';

import { LogIn } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

import { useAuthStore } from '@/stores/auth.store';

export default function RegisterPage() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const register = useAuthStore((state: any) => state.register);
  const isLoading = useAuthStore((state: any) => state.isLoading);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    try {
      await register({ name, email, password });
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <>
      <div className="text-center">
        <div className="mx-auto h-12 w-12 bg-blue-100 dark:bg-blue-900 text-blue-600 dark:text-blue-300 rounded-full flex items-center justify-center mb-4">
          <LogIn className="h-6 w-6" />
        </div>
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Create your account</h2>
        <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
          Or <Link href="/login" className="text-blue-600 hover:text-blue-500">sign in to existing account</Link>
        </p>
      </div>
      <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
        {error && <div className="p-3 bg-red-100 text-red-700 rounded-md text-sm">{error}</div>}
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Full Name</label>
            <input
              type="text"
              required
              className="mt-1 block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500"
              value={name}
              onChange={e => { setName(e.target.value); }}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Email address</label>
            <input
              type="email"
              required
              className="mt-1 block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500"
              value={email}
              onChange={e => { setEmail(e.target.value); }}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Password</label>
            <input
              type="password"
              required
              className="mt-1 block w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-blue-500 focus:border-blue-500"
              value={password}
              onChange={e => { setPassword(e.target.value); }}
            />
          </div>
        </div>
        <button
          type="submit"
          disabled={isLoading}
          className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
        >
          {isLoading ? 'Creating account...' : 'Create account'}
        </button>
      </form>
    </>
  );
}

'use client';

import { Plus, Pin, Folder } from 'lucide-react';
import Link from 'next/link';

import { useWorkspaces } from '@/hooks/use-workspaces';
import { useUIStore } from '@/stores/ui.store';

export default function DashboardPage() {
  const { data: workspaces, isLoading, error } = useWorkspaces();
  const { openCreateWorkspace } = useUIStore();

  if (isLoading) {
    return (
      <div className="animate-pulse space-y-8">
        <div className="h-10 w-48 bg-gray-200 dark:bg-gray-700 rounded"></div>
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-40 bg-gray-200 dark:bg-gray-700 rounded-xl"></div>
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 bg-red-100 text-red-700 rounded-md">
        Error loading workspaces. Please try again.
      </div>
    );
  }

  const pinnedWorkspaces = workspaces?.filter(w => w.isPinned) || [];
  const unpinnedWorkspaces = workspaces?.filter(w => !w.isPinned) || [];

  return (
    <div className="space-y-8">
      <div className="sm:flex sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Your Workspaces</h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            Manage your project contexts and resources.
          </p>
        </div>
        <div className="mt-4 sm:mt-0">
          <button 
            onClick={openCreateWorkspace}
            className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
          >
            <Plus className="-ml-1 mr-2 h-5 w-5" />
            New Workspace
          </button>
        </div>
      </div>

      {pinnedWorkspaces.length > 0 && (
        <section>
          <h2 className="text-sm font-semibold text-gray-900 dark:text-white uppercase tracking-wider mb-4 flex items-center">
            <Pin className="w-4 h-4 mr-2 text-blue-500" /> Pinned
          </h2>
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {pinnedWorkspaces.map(workspace => (
              <WorkspaceCard key={workspace.id} workspace={workspace} />
            ))}
          </div>
        </section>
      )}

      {unpinnedWorkspaces.length > 0 ? (
        <section>
          {pinnedWorkspaces.length > 0 && (
            <h2 className="text-sm font-semibold text-gray-900 dark:text-white uppercase tracking-wider mb-4">
              All Workspaces
            </h2>
          )}
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {unpinnedWorkspaces.map(workspace => (
              <WorkspaceCard key={workspace.id} workspace={workspace} />
            ))}
          </div>
        </section>
      ) : (
        pinnedWorkspaces.length === 0 && (
          <div className="text-center py-16 px-4 sm:px-6 lg:px-8 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl">
            <Folder className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900 dark:text-white">No workspaces</h3>
            <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
              Get started by creating a new workspace.
            </p>
            <div className="mt-6">
              <button 
                onClick={openCreateWorkspace}
                className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
              >
                <Plus className="-ml-1 mr-2 h-5 w-5" />
                New Workspace
              </button>
            </div>
          </div>
        )
      )}
    </div>
  );
}

function WorkspaceCard({ workspace }: { workspace: any }) {
  return (
    <Link 
      href={`/dashboard/workspaces/${workspace.id}`}
      className="block group relative bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 hover:shadow-md hover:border-blue-500 dark:hover:border-blue-500 transition-all duration-200 overflow-hidden"
    >
      <div 
        className="absolute top-0 left-0 w-1 h-full"
        style={{ backgroundColor: workspace.color || '#3B82F6' }}
      />
      <div className="p-6 ml-1">
        <div className="flex justify-between items-start">
          <div className="flex-1 min-w-0">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white truncate flex items-center gap-2">
              {workspace.icon && <span>{workspace.icon}</span>}
              {workspace.name}
            </h3>
            {workspace.description && (
              <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 line-clamp-2">
                {workspace.description}
              </p>
            )}
          </div>
        </div>
        <div className="mt-4 flex items-center justify-between text-xs text-gray-500 dark:text-gray-400">
          <span>{workspace._count?.resources || 0} resources</span>
          <span>{new Date(workspace.createdAt).toLocaleDateString()}</span>
        </div>
      </div>
    </Link>
  );
}

'use client';

import { DndContext, closestCenter, KeyboardSensor, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import { arrayMove, SortableContext, sortableKeyboardCoordinates, verticalListSortingStrategy } from '@dnd-kit/sortable';

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Plus, ArrowLeft, Rocket, AlertTriangle, ExternalLink, X } from 'lucide-react';
import Link from 'next/link';
import { use, useState, useEffect } from 'react';

import type { WorkspaceResource } from '@/hooks/use-workspace-resources';
import type { DragEndEvent } from '@dnd-kit/core';
import { SortableResourceItem } from '@/components/sortable-resource-item';
import { useWorkspaceLaunch } from '@/hooks/use-workspace-launch';
import { useWorkspaceResources } from '@/hooks/use-workspace-resources';
import { useWorkspaces } from '@/hooks/use-workspaces';
import { api } from '@/lib/api';
import { QUERY_KEYS } from '@/lib/query-keys';
import { useUIStore } from '@/stores/ui.store';

export default function WorkspaceDetailPage(props: { params: Promise<{ id: string }> }) {
  const params = use(props.params);
  const workspaceId = params.id;

  const { data: workspaces } = useWorkspaces();
  const workspace = workspaces?.find(w => w.id === workspaceId);
  const { openAddResource } = useUIStore();
  const { data: originalResources, isLoading } = useWorkspaceResources(workspaceId);

  const { launchWorkspace, isLaunching, isLocked, lockCountdown, blockedUrls, clearBlockedUrls } = useWorkspaceLaunch();

  const [resources, setResources] = useState<WorkspaceResource[]>([]);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (originalResources) {
      // Sort by sortOrder
      setResources([...originalResources].sort((a, b) => a.sortOrder - b.sortOrder));
    }
  }, [originalResources]);

  const reorderMutation = useMutation({
    mutationFn: async (orderedIds: string[]) => {
      const data = {
        resourceOrders: orderedIds.map((id, index) => ({ workspaceResourceId: id, sortOrder: index }))
      };
      await api.patch(`/workspaces/${workspaceId}/resources/reorder`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: QUERY_KEYS.workspaceResources.list(workspaceId) });
    }
  });

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      setResources((items) => {
        const oldIndex = items.findIndex(item => item.id === active.id);
        const newIndex = items.findIndex(item => item.id === over.id);

        const newItems = arrayMove(items, oldIndex, newIndex);
        reorderMutation.mutate(newItems.map(item => item.id));
        return newItems;
      });
    }
  };

  if (!workspace) {return null;}

  return (
    <div className="space-y-8 max-w-4xl mx-auto">
      <div className="flex items-center text-sm text-gray-500 hover:text-gray-700 dark:hover:text-gray-300">
        <Link href="/dashboard" className="flex items-center gap-1">
          <ArrowLeft className="w-4 h-4" /> Back to Dashboard
        </Link>
      </div>

      <div className="sm:flex sm:items-center sm:justify-between">
        <div className="flex items-center gap-3">
          <div className="w-2 h-8 rounded-full" style={{ backgroundColor: workspace.color || '#3B82F6' }} />
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
              {workspace.icon && <span>{workspace.icon}</span>}
              {workspace.name}
            </h1>
            {workspace.description && (
              <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                {workspace.description}
              </p>
            )}
          </div>
        </div>
        <div className="mt-4 sm:mt-0 flex items-center gap-3">
          <button 
            onClick={() => launchWorkspace(resources)}
            disabled={isLocked || isLaunching || resources.length === 0}
            className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-green-600 hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLaunching ? (
              <Rocket className="-ml-1 mr-2 h-5 w-5 animate-pulse" />
            ) : (
              <Rocket className="-ml-1 mr-2 h-5 w-5" />
            )}
            {isLocked ? `Wait (${lockCountdown}s)` : 'Launch Workspace'}
          </button>

          <button 
            onClick={() => { openAddResource(workspaceId); }}
            className="inline-flex items-center px-4 py-2 border border-gray-300 dark:border-gray-600 shadow-sm text-sm font-medium rounded-md text-gray-700 dark:text-gray-300 bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700"
          >
            <Plus className="-ml-1 mr-2 h-5 w-5" />
            Add Resource
          </button>
        </div>
      </div>

      {blockedUrls.length > 0 && (
        <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 rounded-lg p-4">
          <div className="flex items-start">
            <div className="flex-shrink-0">
              <AlertTriangle className="h-5 w-5 text-yellow-600 dark:text-yellow-500" />
            </div>
            <div className="ml-3 flex-1">
              <h3 className="text-sm font-medium text-yellow-800 dark:text-yellow-400">
                Popup Blocker Detected
              </h3>
              <div className="mt-2 text-sm text-yellow-700 dark:text-yellow-300">
                <p>Your browser prevented {blockedUrls.length} tabs from opening automatically. Please allow popups for DevFlow Hub, or click the links below manually:</p>
                <ul className="mt-3 flex flex-wrap gap-2">
                  {blockedUrls.map((url, idx) => (
                    <li key={idx}>
                      <a 
                        href={url} 
                        target="_blank" 
                        rel="noreferrer"
                        className="inline-flex items-center px-3 py-1 bg-yellow-100 dark:bg-yellow-800 text-yellow-800 dark:text-yellow-200 rounded-md hover:bg-yellow-200 dark:hover:bg-yellow-700"
                      >
                        {url} <ExternalLink className="ml-1 h-3 w-3" />
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
            <button onClick={clearBlockedUrls} className="ml-4 text-yellow-600 hover:text-yellow-700">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
      )}

      <div className="bg-gray-50 dark:bg-gray-900 rounded-xl p-4 min-h-[300px]">
        {isLoading ? (
          <div className="animate-pulse space-y-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-16 bg-gray-200 dark:bg-gray-800 rounded-lg"></div>
            ))}
          </div>
        ) : resources.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-sm text-gray-500 dark:text-gray-400">No resources yet. Add your first link or app!</p>
          </div>
        ) : (
          <DndContext 
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext 
              items={resources.map(r => r.id)}
              strategy={verticalListSortingStrategy}
            >
              <div className="space-y-3">
                {resources.map((item) => (
                  <SortableResourceItem key={item.id} item={item} />
                ))}
              </div>
            </SortableContext>
          </DndContext>
        )}
      </div>
    </div>
  );
}

'use client';

import { LayoutDashboard, LogOut, Loader2, Plus, Menu, X } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { useState } from 'react';

import AddResourceModal from '@/components/modals/add-resource-modal';
import CreateWorkspaceModal from '@/components/modals/create-workspace-modal';
import { useAuthStore } from '@/stores/auth.store';

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const { isAuthenticated, isLoading, checkAuth, user, logout } = useAuthStore();
  const router = useRouter();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push('/login');
    }
  }, [isLoading, isAuthenticated, router]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!isAuthenticated) {return null;}

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 z-20 bg-black/50 lg:hidden"
          onClick={() => { setIsSidebarOpen(false); }}
        />
      )}

      {/* Sidebar */}
      <aside 
        className={`fixed inset-y-0 left-0 z-30 w-64 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 transform transition-transform duration-200 ease-in-out lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}
      >
        <div className="h-full flex flex-col">
          <div className="h-16 flex items-center px-6 border-b border-gray-200 dark:border-gray-700 justify-between">
            <span className="text-xl font-bold text-gray-900 dark:text-white">DevFlow Hub</span>
            <button className="lg:hidden text-gray-500" onClick={() => { setIsSidebarOpen(false); }}>
              <X className="h-6 w-6" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto py-4">
            <nav className="px-4 space-y-1">
              <Link 
                href="/dashboard" 
                className="flex items-center px-2 py-2 text-sm font-medium rounded-md bg-blue-50 text-blue-700 dark:bg-blue-900/50 dark:text-blue-200"
              >
                <LayoutDashboard className="mr-3 h-5 w-5 flex-shrink-0" />
                Dashboard
              </Link>
              {/* Future sidebar links can go here */}
            </nav>
          </div>

          <div className="p-4 border-t border-gray-200 dark:border-gray-700">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <div className="h-8 w-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold uppercase">
                  {user?.name?.[0] || 'U'}
                </div>
              </div>
              <div className="ml-3 truncate">
                <p className="text-sm font-medium text-gray-900 dark:text-white truncate">{user?.name}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{user?.email}</p>
              </div>
            </div>
            <button
              onClick={() => logout()}
              className="mt-4 flex w-full items-center px-2 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md"
            >
              <LogOut className="mr-3 h-5 w-5" />
              Sign Out
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="bg-white dark:bg-gray-800 shadow-sm border-b border-gray-200 dark:border-gray-700 lg:hidden">
          <div className="h-16 px-4 flex items-center justify-between">
            <button 
              onClick={() => { setIsSidebarOpen(true); }}
              className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 focus:outline-none"
            >
              <Menu className="h-6 w-6" />
            </button>
            <span className="text-lg font-bold text-gray-900 dark:text-white">DevFlow Hub</span>
