import { create } from 'zustand';

import { api } from '../lib/api';

import type { ApiResponse } from '@repo/types';
import type { LoginInput, RegisterInput } from '@repo/validation';

export interface User {
  id: string;
  email: string;
  name: string;
  avatarUrl?: string | null;
}

interface AuthState {
  user: User | null;
  accessToken: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  setAccessToken: (token: string | null) => void;
  login: (data: LoginInput) => Promise<void>;
  register: (data: RegisterInput) => Promise<void>;
  logout: () => Promise<void>;
  checkAuth: () => Promise<void>;
}

export const useAuthStore = create<AuthState>((set, get) => ({
  user: null,
  accessToken: null,
  isAuthenticated: false,
  isLoading: true,

  setAccessToken: (token: string | null) => {
    set({ accessToken: token, isAuthenticated: !!token });
  },

  login: async (data: LoginInput) => {
    try {
      set({ isLoading: true });
      const res = await api.post<any, ApiResponse<{ accessToken: string }>>('/auth/login', data);
      if (res.data?.accessToken) {
        set({ accessToken: res.data.accessToken, isAuthenticated: true });
        await get().checkAuth();
      }
    } finally {
      set({ isLoading: false });
    }
  },

  register: async (data: RegisterInput) => {
    try {
      set({ isLoading: true });
      const res = await api.post<any, ApiResponse<{ accessToken: string }>>('/auth/register', data);
      if (res.data?.accessToken) {
        set({ accessToken: res.data.accessToken, isAuthenticated: true });
        await get().checkAuth();
      }
    } finally {
      set({ isLoading: false });
    }
  },

  logout: async () => {
    try {
      await api.post('/auth/logout');
    } catch (error) {
      console.error('Logout error', error);
    } finally {
      set({ user: null, accessToken: null, isAuthenticated: false });
      window.location.href = '/login';
    }
  },

  checkAuth: async () => {
    try {
      set({ isLoading: true });
      // If we don't have an access token, try to refresh first (which sets it via interceptor or manually)
      if (!get().accessToken) {
        const res = await api.post<any, ApiResponse<{ accessToken: string }>>('/auth/refresh');
        if (res.data?.accessToken) {
          set({ accessToken: res.data.accessToken, isAuthenticated: true });
        }
      }

      // Fetch user profile
      const userRes = await api.get<any, ApiResponse<User>>('/auth/me');
      if (userRes.data) {
        set({ user: userRes.data, isAuthenticated: true });
      }
    } catch (error) {
      set({ user: null, accessToken: null, isAuthenticated: false });
    } finally {
      set({ isLoading: false });
    }
  },
}));
